import React, { useState, useEffect } from 'react';
import { io } from 'socket.io-client';
import Lobby from './components/Lobby';
import GameBoard from './components/GameBoard';
import './App.css';

const socket = io('http://localhost:5000');

function App() {
  const [gameState, setGameState] = useState(null);
  const [player, setPlayer] = useState(null);
  const [currentView, setCurrentView] = useState('lobby'); // 'lobby' or 'game' or 'single-player'
  const [error, setError] = useState(null);
  const [isSinglePlayer, setIsSinglePlayer] = useState(false);

  useEffect(() => {
    // Socket event listeners
    socket.on('joinedGame', (data) => {
      setGameState(data.game);
      setPlayer(data.player);
      setCurrentView('game');
      setError(null);
    });

    socket.on('playerJoined', (data) => {
      setGameState(data.game);
    });

    socket.on('gameStarted', (data) => {
      setGameState(data.game);
    });

    socket.on('cardPlayed', (data) => {
      setGameState(data.game);
    });

    socket.on('cardDrawn', (data) => {
      setGameState(data.game);
    });

    socket.on('playerLeft', (data) => {
      setGameState(data.game);
    });

    socket.on('error', (data) => {
      setError(data.message);
    });

    return () => {
      socket.off('joinedGame');
      socket.off('playerJoined');
      socket.off('gameStarted');
      socket.off('cardPlayed');
      socket.off('cardDrawn');
      socket.off('playerLeft');
      socket.off('error');
    };
  }, []);

  const joinGame = (gameId, playerName) => {
    socket.emit('joinGame', { gameId, playerName });
  };

  const startGame = () => {
    if (gameState) {
      socket.emit('startGame', { gameId: gameState._id });
    }
  };

  const playCard = (cardId, chosenColor = null) => {
    if (gameState) {
      socket.emit('playCard', { gameId: gameState._id, cardId, chosenColor });
    }
  };

  const drawCard = () => {
    if (gameState) {
      socket.emit('drawCard', { gameId: gameState._id });
    }
  };

  const createGame = async (playerName) => {
    try {
      const response = await fetch('/api/games', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      const data = await response.json();
      joinGame(data.roomCode, playerName);
    } catch (error) {
      setError('Failed to create game. Please try again.');
    }
  };

  const startSinglePlayer = (playerName) => {
    setIsSinglePlayer(true);
    setPlayer({ name: playerName, _id: 'player1' });
    setCurrentView('single-player');
    // Initialize a simple single player game
    setGameState({
      _id: 'single-player-game',
      roomCode: 'SINGLE',
      status: 'playing',
      players: [{ name: playerName, _id: 'player1' }, { name: 'Computer', _id: 'computer' }],
      currentPlayer: 0,
      discardPile: [{ color: 'red', value: '0' }],
      drawPile: [], // Simplified
    });
  };

  const startMultiplayer = (playerName) => {
    setIsSinglePlayer(false);
    createGame(playerName);
  };

  const leaveGame = () => {
    if (gameState) {
      if (!isSinglePlayer) {
        socket.emit('leaveGame', { gameId: gameState._id });
      }
      setGameState(null);
      setPlayer(null);
      setCurrentView('lobby');
      setIsSinglePlayer(false);
    }
  };

  return (
    <div className="app">
      <h1>UNO Game</h1>
      {error && <div className="error">{error}</div>}
      {currentView === 'lobby' ? (
        <Lobby onSinglePlayer={startSinglePlayer} onMultiplayer={startMultiplayer} />
      ) : currentView === 'single-player' ? (
        <div className="single-player-mode">
          <h2>Single Player Mode</h2>
          <p>Game Room: {gameState?.roomCode}</p>
          <p>Status: {gameState?.status}</p>
          <p>Current Player: {gameState?.players[gameState?.currentPlayer]?.name}</p>
          <p>Single player mode is simplified. Full implementation coming soon!</p>
          <button onClick={leaveGame} className="leave-button">Back to Lobby</button>
        </div>
      ) : (
        <GameBoard
          gameState={gameState}
          player={player}
          onStartGame={startGame}
          onPlayCard={playCard}
          onDrawCard={drawCard}
          onLeaveGame={leaveGame}
        />
      )}
    </div>
  );
}

export default App;
